function export:In()
	-- Intro skip stuff
	Globals.MASTER_GameGlobals.FinishedIntro = 1;
	DisablePostFx("blackscreennowfxhighpriority");
	CGameMissionMgr_GetInstance():GetMission("Missions/Outposts/w1_c_3/zXmOLgx"):Enable();

	-- Update 3.7: Fix for an issue where if the player starts a new game, doesn't skip the intro but then quits to the menu and does skip it, AI is still in scripted mode
